INSERT INTO _migration_625_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_039', 'topic_bece_science_health', 'subj_bece_science', 'exam_bece', NULL, NULL, 'In a village, 200 out of 250 children have been immunised against measles. Calculate the percentage of children immunised.', 'calculation', NULL, NULL, '80%', 'Percentage immunised = (number immunised ÷ total number of children) × 100 = (200 ÷ 250) × 100 = 0.8 × 100 = 80%. Answer: 80% of the children have been immunised.', 'easy', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_040', 'topic_bece_science_health', 'subj_bece_science', 'exam_bece', NULL, NULL, 'There has been an outbreak of cholera in a nearby town, and the school health club is preparing a talk on it.', 'structured', NULL, NULL, '(a) A communicable disease is one that can be passed from one person (or animal) to another, for example through water, food, air or body contact (1). (b) Drinking water contaminated with the cholera germs (1); eating food contaminated by dirty hands, flies or contaminated water (1). (c) Any two of: boil or chlorinate drinking water; wash hands with soap after using the toilet and before handling food; dispose of refuse and faeces safely; cover food and keep it away from flies; report cases quickly and treat patients with oral rehydration (1 each).', '(a) A communicable disease is one that can be passed from one person (or animal) to another, for example through water, food, air or body contact (1). (b) Drinking water contaminated with the cholera germs (1); eating food contaminated by dirty hands, flies or contaminated water (1). (c) Any two of: boil or chlorinate drinking water; wash hands with soap after using the toilet and before handling food; dispose of refuse and faeces safely; cover food and keep it away from flies; report cases quickly and treat patients with oral rehydration (1 each).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_041', 'topic_bece_science_methods', 'subj_bece_science', 'exam_bece', NULL, NULL, 'When reading the volume of water in a measuring cylinder, the eye must be level with the bottom of the meniscus. What error does this prevent?', 'multiple_choice', NULL, '["A. Parallax error, which gives a reading that is too high or too low","B. Zero error, which comes from a faulty scale","C. Expansion of the water as it warms up","D. Evaporation of the water during the reading"]', 'A', 'If the eye is above or below the meniscus, the line of sight makes the water level appear higher or lower than it really is — a parallax error. Reading with the eye level with the bottom of the meniscus gives the true volume. (Zero error is a fault of the instrument itself, and evaporation is far too slow to affect a single reading.) Therefore the correct answer is A: Parallax error, which gives a reading that is too high or too low.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_042', 'topic_bece_science_methods', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A class investigates whether seedlings grow taller with more water. They give one group 50 cm³ of water a day and another group 100 cm³ a day. Which variable must be kept the same for a fair test?', 'multiple_choice', NULL, '["A. The amount of water given to each pot","B. The type and amount of soil in each pot","C. The height the seedlings finally reach","D. The colour of the measuring cylinder"]', 'B', 'In a fair test only the variable being investigated — the amount of water — is changed; every other factor that could affect growth, such as the soil, the pot size, the type of seed and the sunlight, must be kept constant. Otherwise no one can tell whether the water or some other difference caused the result. (The final height is the variable being measured, so it is expected to differ, and cylinder colour cannot affect growth.) Therefore the correct answer is B: The type and amount of soil in each pot.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Evaluate', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_043', 'topic_bece_science_methods', 'subj_bece_science', 'exam_bece', NULL, NULL, 'List the first four stages of the scientific method, in the correct order.', 'short_answer', NULL, NULL, 'Observation of a problem; asking a question and forming a hypothesis; experimenting to test the hypothesis; recording the results and drawing a conclusion.', 'Scientific investigation begins with careful observation, which raises a question; the investigator then forms a hypothesis — a testable suggested answer; next an experiment is designed and carried out to test the hypothesis; finally the results are recorded and analysed so that a conclusion can be drawn about whether the hypothesis was supported. Answer: observation → hypothesis → experiment → results and conclusion.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'Sequence', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_044', 'topic_bece_science_methods', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A learner measures the length of a leaf three times and gets 5.2 cm, 5.4 cm and 5.3 cm. Calculate the average (mean) length of the leaf.', 'calculation', NULL, NULL, '5.3 cm', 'Mean = (5.2 + 5.4 + 5.3) cm ÷ 3 = 15.9 cm ÷ 3 = 5.3 cm. Answer: the average length of the leaf is 5.3 cm.', 'easy', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_625_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_040_a', 'q_bece_intsci_s3_040', 'a', 'Explain what is meant by a communicable disease.', '1', 'A communicable disease is one that can be passed from one person (or animal) to another, for example through water, food, air or body contact (1).', '1'),
('sqp_q_bece_intsci_s3_040_b', 'q_bece_intsci_s3_040', 'b', 'State two ways in which cholera is spread.', '2', 'Drinking water contaminated with the cholera germs (1); eating food contaminated by dirty hands, flies or contaminated water (1).', '2'),
('sqp_q_bece_intsci_s3_040_c', 'q_bece_intsci_s3_040', 'c', 'State two measures the community can take to control the outbreak.', '2', 'Any two of: boil or chlorinate drinking water; wash hands with soap after using the toilet and before handling food; dispose of refuse and faeces safely; cover food and keep it away from flies; report cases quickly and treat patients with oral rehydration (1 each).', '3');
INSERT INTO _migration_625_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_625_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_625_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_625_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_625_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_625_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_625_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_625_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_625_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_625_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_625_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_625_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
